import{_ as t,a as s,b as a,c as n}from"./chunks/tritanopia.75ysa3L8.js";import{_ as o,o as r,c as i,a3 as l}from"./chunks/framework.BlfGB29P.js";const d="/assets/blocks-for-ha/grid/fr/light.png",u="/assets/blocks-for-ha/grid/fr/dark.png",c="/assets/blocks-for-ha/themes/fr/dark.png",p="/assets/blocks-for-ha/themes/fr/tritanopia.png",q=JSON.parse('{"title":"Thèmes et zoom","description":"","frontmatter":{"title":"Thèmes et zoom"},"headers":[],"relativePath":"fr/projects/blocks-for-ha/themes.md","filePath":"fr/projects/blocks-for-ha/themes.md","lastUpdated":1793128957000}'),m={name:"fr/projects/blocks-for-ha/themes.md"};function g(b,e,h,f,k,v){return r(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="themes-et-zoom" tabindex="-1">Thèmes et zoom <a class="header-anchor" href="#themes-et-zoom" aria-label="Permalink to &quot;Thèmes et zoom&quot;">​</a></h1><h2 id="logique-et-objets-depuis-0-1-56" tabindex="-1">Logique et Objets depuis 0.1.56 <a class="header-anchor" href="#logique-et-objets-depuis-0-1-56" aria-label="Permalink to &quot;Logique et Objets depuis 0.1.56&quot;">​</a></h2><p>Dans Standard/Dark, les blocs logiques sont bleus et les objets bruns, avec des libellés blancs lisibles. Modern et Tritanopia conservent leurs propres palettes. <strong>Si / sinon si / sinon</strong> est désormais disponible dans <strong>Logique</strong> : l’engrenage ouvre le constructeur de branches ; les branches sinon si et Sinon peuvent y être ajoutées ou retirées. Les conditions et séquences d’actions produisent une branche native HA. Les projets existants restent compatibles.</p><h2 id="grille-de-points-depuis-0-1-51" tabindex="-1">Grille de points depuis 0.1.51 <a class="header-anchor" href="#grille-de-points-depuis-0-1-51" aria-label="Permalink to &quot;Grille de points depuis 0.1.51&quot;">​</a></h2><p>L’espace de travail affiche une grille native Blockly bien visible, avec un espacement de 25 unités et l’alignement automatique, inspirée de <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/BlocklyEditor.tsx" target="_blank" rel="noreferrer">l’éditeur Blockly d’ioBroker</a>. Le fond et les points suivent immédiatement l’apparence <strong>Clair / Sombre / Système</strong>, y compris les changements du système. La palette Blockly détermine toujours les couleurs des blocs et des menus ; le fond suit l’application même avec la palette Dark.</p><p>Le zoom et le déplacement font suivre la grille. Ajuster ne modifie pas la taille des blocs du menu. L’apparence et la palette ne changent ni l’automatisation ni le YAML.</p><p><img src="'+d+'" alt="Grille claire"></p><p><img src="'+u+'" alt="Grille sombre"></p><p>Depuis <strong>0.1.27</strong>, les blocs UGSo Standard/Dark utilisent des libellés blancs. Les fonds bleus et bruns intermédiaires sont légèrement assombris pour un contraste d’au moins <strong>4,5:1</strong>. Les couleurs claires originales de Modern/Tritanopia utilisent une écriture sombre suffisamment contrastée. Les champs éditables restent distincts et lisibles. Les images DE/EN/FR du catalogue ont été régénérées avec cette correction.</p><p>Le thème de l’application et la palette Blockly sont <strong>indépendants</strong>. La langue des blocs est également un réglage distinct. Ni thèmes ni zoom ni langue ne modifient le YAML.</p><h2 id="palette-blockly" tabindex="-1">Palette Blockly <a class="header-anchor" href="#palette-blockly" aria-label="Permalink to &quot;Palette Blockly&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Choix</th><th>Apparence</th><th>Source originale</th></tr></thead><tbody><tr><td>UGSo Standard</td><td>Couleurs des groupes UGSo, menu sombre et panneau de blocs clair</td><td>Adaptation UGSo de Blockly Classic</td></tr><tr><td>Dark</td><td>Espace de travail et panneau sombres, fond du menu distinct</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-dark" target="_blank" rel="noreferrer">theme-dark</a></td></tr><tr><td>Modern</td><td>Palette Modern originale avec bordures marquées et groupes UGSo</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-modern" target="_blank" rel="noreferrer">theme-modern</a></td></tr><tr><td>Tritanopia</td><td>Palette des groupes standard adaptée, complétée pour les groupes HA</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-tritanopia" target="_blank" rel="noreferrer">theme-tritanopia</a></td></tr></tbody></table><p>Tritanopia vise les personnes présentant cette déficience de vision des couleurs. Les blocs clairs ont des libellés sombres, les blocs sombres des libellés clairs. Les champs éditables restent visuellement distincts. Les noms des catégories apportent un repère supplémentaire. Cela ne constitue pas une certification complète d’accessibilité.</p><p><img src="'+c+'" alt="Palette Dark, blocs français"></p><p><img src="'+p+'" alt="Palette Tritanopia, blocs français"></p><p>Le choix est sauvegardé localement. Une préférence inconnue revient au standard ; si le stockage est bloqué, le changement reste possible pour la page actuelle.</p><h2 id="zoom" tabindex="-1">Zoom <a class="header-anchor" href="#zoom" aria-label="Permalink to &quot;Zoom&quot;">​</a></h2><p>Depuis <strong>0.1.40</strong>, tous les thèmes utilisent une <strong>police de 16 px</strong>. Le menu de blocs reste à <strong>100 %</strong> : ajustement, molette et zoom modifient uniquement l’espace de travail. Zoom initial 100 %, ajustement 85–120 %, zoom manuel 50–240 %. Les grandes automatisations restent défilables ; l’ajustement ne descend pas sous 85 % afin de préserver la lisibilité. Vérifié en Full HD, 2560 px et HiDPI.</p><h2 id="apparence-de-l-application" tabindex="-1">Apparence de l’application <a class="header-anchor" href="#apparence-de-l-application" aria-label="Permalink to &quot;Apparence de l’application&quot;">​</a></h2><p><strong>Darstellung</strong> propose <strong>Hell</strong>, <strong>Dunkel</strong> et <strong>System</strong> pour l’en-tête, les panneaux, formulaires, YAML, dialogues et éditeurs. System suit immédiatement la préférence de couleur du navigateur/système ; un choix manuel la remplace. Préférence locale, indépendante de la palette Blockly. Le badge Built with Blockly utilise automatiquement la variante adaptée.</p><p>Blockly et les plugins de thèmes/zoom sont épinglés à 13.3.0 et intégrés localement sous Apache-2.0. <a href="./blocks">Catalogue et liens des plugins</a>.</p><details class="details custom-block"><summary>Référence détaillée issue de la documentation allemande</summary><h2 id="themes-und-zoom" tabindex="-1">Thèmes et zoom <a class="header-anchor" href="#themes-und-zoom" aria-label="Permalink to &quot;Thèmes et zoom {#themes-und-zoom}&quot;">​</a></h2><h3 id="logik-und-objekte-seit-0-1-56" tabindex="-1">Logique et objets depuis 0.1.56 <a class="header-anchor" href="#logik-und-objekte-seit-0-1-56" aria-label="Permalink to &quot;Logique et objets depuis 0.1.56 {#logik-und-objekte-seit-0-1-56}&quot;">​</a></h3><p>Dans les thèmes « Standard » et « Dark », les blocs de logique sont bleus et les blocs d&#39;objets sont bruns, avec un texte blanc bien lisible. Les thèmes « Modern » et « Tritanopia » conservent leurs propres palettes. La structure <strong>Si / Sinon si / Sinon</strong> est désormais intégrée directement dans la section <strong>Logique</strong> : l&#39;icône en forme de roue dentée ouvre un menu permettant de gérer les branches supplémentaires (ajout ou suppression de branches et du bloc « Sinon »). Les conditions et les chaînes d&#39;actions sont générées sous forme de structures conditionnelles natives de HA. Les projets existants restent compatibles.</p><h3 id="punktraster-seit-0-1-51" tabindex="-1">Grille de points depuis 0.1.51 <a class="header-anchor" href="#punktraster-seit-0-1-51" aria-label="Permalink to &quot;Grille de points depuis 0.1.51 {#punktraster-seit-0-1-51}&quot;">​</a></h3><p>L&#39;espace de travail affiche une grille de points Blockly native, clairement visible, avec un espacement de 25 unités et une fonction d&#39;alignement (magnétisme), inspirée de l&#39;<a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/BlocklyEditor.tsx" target="_blank" rel="noreferrer">éditeur Blockly d&#39;ioBroker</a>. L&#39;arrière-plan et les points s&#39;adaptent instantanément au mode d&#39;affichage de l&#39;application (<strong>Clair / Sombre / Système</strong>), y compris en cas de modification des paramètres système. Le choix du thème Blockly détermine toujours les couleurs des blocs et des menus ; l&#39;espace de travail suit le mode d&#39;affichage de l&#39;application, même lorsque la palette « Sombre » est sélectionnée.</p><p>Le zoom et le déplacement (panoramique) entraînent la grille en même temps que l&#39;espace de travail. L&#39;ajustement à l&#39;écran (« Fit ») ne modifie pas la taille des blocs dans les menus. Le mode d&#39;affichage et la palette n&#39;affectent ni les automatisations ni le code YAML.</p><p><img src="'+t+'" alt="Grille de points en mode clair"></p><p><img src="'+s+'" alt="Grille de points en mode sombre"></p><p>Depuis la version <strong>0.1.27</strong>, les blocs UGSo (en modes Standard/Sombre) présentent des libellés en blanc. Les zones bleues et brunes de teinte moyenne sont légèrement assombries pour garantir un rapport de contraste d&#39;au moins <strong>4,5:1</strong>. Pour les couleurs claires d&#39;origine (thèmes « Modern » / « Tritanopia »), une police sombre offrant un contraste suffisant est utilisée. Les champs de saisie restent lisibles indépendamment. Les visuels des blocs dans le catalogue ont été régénérés pour les langues DE/EN/FR en intégrant cette correction.</p><p>Depuis la version <strong>0.1.16</strong>, la barre d&#39;outils située au-dessus de l&#39;espace de travail inclut un <strong>sélecteur de thème</strong>. Celui-ci s&#39;applique à l&#39;environnement Blockly, y compris aux catégories, au sélecteur de blocs et aux blocs eux-mêmes. La palette Blockly est indépendante du mode d&#39;affichage de l&#39;application. Le nombre de types de blocs reste inchangé (111).</p><table tabindex="0"><thead><tr><th>Sélection</th><th>Affichage</th><th>Source originale</th></tr></thead><tbody><tr><td>UGSo Standard</td><td>Couleurs de groupe UGSo habituelles, menu sombre et sélection de blocs claire</td><td>Personnalisation UGSo spécifique basée sur Blockly Classic</td></tr><tr><td>Dark</td><td>Espace de travail sombre, sélection de blocs sombre et menu des catégories distinct</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-dark" target="_blank" rel="noreferrer">theme-dark</a></td></tr><tr><td>Modern</td><td>Palette « Modern » originale avec des bordures plus marquées et groupes d&#39;extension UGSo</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-modern" target="_blank" rel="noreferrer">theme-modern</a></td></tr><tr><td>Tritanopia</td><td>Palette originale pour les groupes standard et couleurs supplémentaires pour les groupes spécifiques à HA</td><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-tritanopia" target="_blank" rel="noreferrer">theme-tritanopia</a></td></tr></tbody></table><p>Le mode « Tritanopia » est conçu pour les personnes présentant ce type de trouble de la vision des couleurs. Les blocs et catégories propres à UGSo utilisent désormais des styles de thème plutôt que des couleurs fixes. Les blocs clairs présentent des inscriptions sombres, tandis que les blocs sombres affichent des inscriptions claires ; les champs de saisie restent lisibles. La catégorie sélectionnée, quelle que soit la palette utilisée, présente un fond sombre avec une écriture claire. Les noms des catégories et le texte des blocs restent visibles pour faciliter le repérage. Ceci ne constitue pas une certification complète en matière d&#39;accessibilité.</p><p><img src="'+a+'" alt="Mode « Dark » dans l&#39;éditeur UGSo"></p><p><img src="'+n+'" alt="Mode « Tritanopia » dans l&#39;éditeur UGSo"></p><h3 id="wechseln-und-speichern" tabindex="-1">Changer et enregistrer <a class="header-anchor" href="#wechseln-und-speichern" aria-label="Permalink to &quot;Changer et enregistrer {#wechseln-und-speichern}&quot;">​</a></h3><p>Le thème est commuté instantanément, sans qu&#39;il soit nécessaire de reconstruire l&#39;espace de travail. Les blocs, les connexions, la disposition et le code YAML sont conservés. Ce choix est enregistré dans le navigateur — indépendamment du projet — et est réappliqué après un rechargement de la page. Les fichiers de projet et le code YAML ne transmettent pas ce paramètre d&#39;affichage aux autres navigateurs. En cas de paramètres inconnus, le système revient au thème par défaut « UGSo » ; si le stockage du navigateur est bloqué, le changement reste effectif pour la session en cours.</p><p>Le moteur de rendu <strong>Geras</strong> existant demeure actif pour tous les thèmes, garantissant ainsi la préservation de la géométrie des connecteurs et des modalités d&#39;interaction. Le thème « Modern » original préconise l&#39;utilisation de Zelos/Thrasos ; dans ce contexte, sa palette de couleurs et de bordures est appliquée et validée avec Geras. Le changement de moteur de rendu ne constitue pas une option supplémentaire dans cette version.</p><h3 id="alle-blocks-einpassen" tabindex="-1">Ajuster tous les blocs <a class="header-anchor" href="#alle-blocks-einpassen" aria-label="Permalink to &quot;Ajuster tous les blocs {#alle-blocks-einpassen}&quot;">​</a></h3><p>La fonctionnalité originale <a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/zoom-to-fit" target="_blank" rel="noreferrer">zoom-to-fit</a> est complétée par une icône représentant quatre flèches, située à côté des commandes de zoom. Un simple clic permet d&#39;ajuster les blocs à l&#39;espace de travail disponible. Ce bouton est également accessible via la touche Tabulation et peut être activé avec les touches Entrée ou Espace. Le zoom modifie la vue, mais n&#39;affecte pas l&#39;automatisation elle-même.</p><p>Depuis <strong>0.1.40</strong>, les blocs utilisent une police de <strong>16 px</strong> dans tous les thèmes. Le menu des blocs reste fixé à <strong>100 %</strong> : les fonctions d&#39;ajustement, la molette de la souris et les commandes de zoom n&#39;agissent que sur l&#39;espace de travail. Le zoom initial est de 100 %, l&#39;ajustement automatique varie entre 85 % et 120 %, et le zoom manuel est possible de 50 % à 240 %. Les automatisations de grande taille restent déplaçables ; la fonction d&#39;ajustement ne réduit leur taille qu&#39;à 85 % au minimum, afin de garantir la lisibilité du texte. Testé en résolution Full HD, 2560 px et sur écrans HiDPI.</p><p>Les quatre plugins originaux supplémentaires sont définis sur <strong>13.3.0</strong>, intègrent Blockly via <strong>13.3.0</strong> et sont sous licence Apache (<strong>2.0</strong>). Les six plugins originaux existants restent sous <strong>13.2.0</strong>. Les paquets sont fournis localement ; aucune dépendance externe (fichiers de thème ou CDN). Les sources originales et les mentions de licence sont également disponibles dans le <a href="/fr/projects/blocks-for-ha/blocks">catalogue de blocs</a>.</p><p>Éléments vérifiés : quatre thèmes, typographie sur les blocs clairs (mode Tritanopie), sortie projet/YAML inchangée, mémorisation de la sélection, gestion des paramètres de stockage inconnus ou verrouillés, ajustement à l&#39;écran et largeur pour mobile. Le fonctionnement de HA (Home Assistant) n&#39;est pas altéré par cette modification d&#39;affichage.</p><h3 id="app-darstellung-hell-dunkel-oder-system" tabindex="-1">Apparence de l&#39;application : Clair, Sombre ou Système <a class="header-anchor" href="#app-darstellung-hell-dunkel-oder-system" aria-label="Permalink to &quot;Apparence de l&#39;application : Clair, Sombre ou Système {#app-darstellung-hell-dunkel-oder-system}&quot;">​</a></h3><p>Depuis <strong>0.1.22</strong>, une option d&#39;<strong>affichage</strong> est disponible dans l&#39;en-tête, proposant les modes <strong>Clair</strong>, <strong>Sombre</strong> et <strong>Système</strong> pour l&#39;ensemble de l&#39;interface de l&#39;application : en-tête, panneaux, formulaires, sortie YAML, boîtes de dialogue, sélecteur d&#39;entités et éditeur de blocs/modèles personnalisé. Le mode « Système » est activé par défaut ; toute modification de la préférence de couleur au niveau du système d&#39;exploitation ou du navigateur est immédiatement prise en compte. Une sélection manuelle prévaut sur le réglage système. Ce paramètre est enregistré localement dans le navigateur ; si le stockage du navigateur est désactivé, le changement de mode reste fonctionnel pour la page en cours.</p><p>Les thèmes Blockly restent sélectionnables séparément dans la barre d&#39;outils, incluant notamment les thèmes « Modern » et « Tritanopia ». Le choix de l&#39;affichage n&#39;affecte ni les blocs, ni le code YAML généré, ni les projets. Le badge original « Built-with-Blockly » s&#39;adapte automatiquement à la variante claire ou sombre correspondante.</p></details>',22)])])}const x=o(m,[["render",g]]);export{q as __pageData,x as default};
